import java.io.InputStream;
import java.io.OutputStream;
import java.io.PrintWriter;
import java.util.InputMismatchException;

public class Main {
    public static void main(String[] args) {
        InputStream is = System.in;
        OutputStream os = System.out;
        Reader in = new Reader(is);
        PrintWriter out = new PrintWriter(os);
        Solver solver = new Solver();
        solver.process(1, in, out);
        out.flush();
    }

    static class Solver {
        static final int MAX_SIZE = 1 << 20;
        static double[] cosTable = new double[MAX_SIZE];
        static double[] sinTable = new double[MAX_SIZE];
        static double[] cosNegTable = new double[MAX_SIZE];
        static double[] sinNegTable = new double[MAX_SIZE];

        static {
            for (int seg = 1; seg <= MAX_SIZE; seg <<= 1) {
                int mid = seg >> 1;
                for (int i = mid; i < seg; i++) {
                    double angle = 2 * Math.PI * (i - mid) / seg;
                    cosTable[i] = Math.cos(angle);
                    sinTable[i] = Math.sin(angle);
                    cosNegTable[i] = Math.cos(-angle);
                    sinNegTable[i] = Math.sin(-angle);
                }
            }
        }

        void process(int testCase, Reader reader, PrintWriter writer) {
            final int MOD = 998244353;
            int n = reader.nextInt();
            int k = reader.nextInt();
            int[] base = new int[10];
            for (int i = 0; i < k; i++) {
                int pos = reader.nextInt();
                base[pos] = 1;
            }

            int[] current = {1};
            int power = n / 2;

            while (true) {
                if ((power & 1) == 1) {
                    current = multiply(current, base, MOD);
                }
                power >>= 1;
                if (power == 0) break;
                base = multiply(base, base, MOD);
            }

            long sum = 0;
            for (int val : current) {
                sum += (long) val * val;
            }
            writer.println(sum % MOD);
        }

        int[] multiply(int[] a, int[] b, int mod) {
            int required = a.length + b.length - 1;
            int size = Math.max(2, Integer.highestOneBit(required - 1) << 1);

            double[] reA = new double[size];
            double[] imA = new double[size];
            for (int i = 0; i < a.length; i++) {
                int x = ((a[i] % mod) + mod) % mod;
                reA[i] = x & 0x7FFF;
                imA[i] = x >>> 15;
            }
            transform(reA, imA, false);

            double[] reB = new double[size];
            double[] imB = new double[size];
            for (int i = 0; i < b.length; i++) {
                int x = ((b[i] % mod) + mod) % mod;
                reB[i] = x & 0x7FFF;
                imB[i] = x >>> 15;
            }
            transform(reB, imB, false);

            double[] reRes = new double[size];
            double[] imRes = new double[size];

            for (int i = 0; i < size; i++) {
                int j = (size - i) & (size - 1);
                double ar1 = (reA[i] + reA[j]) * 0.5;
                double ai1 = (imA[i] - imA[j]) * 0.5;
                double ar2 = (imA[i] + imA[j]) * 0.5;
                double ai2 = (reA[j] - reA[i]) * 0.5;

                double br1 = (reB[i] + reB[j]) * 0.5;
                double bi1 = (imB[i] - imB[j]) * 0.5;
                double br2 = (imB[i] + imB[j]) * 0.5;
                double bi2 = (reB[j] - reB[i]) * 0.5;

                reRes[i] = ar1 * br1 - ai1 * bi1 - ar2 * bi2 - ai2 * br2;
                imRes[i] = ar1 * bi1 + ai1 * br1 + ar2 * br2 - ai2 * bi2;
            }

            transform(reRes, imRes, true);
            int[] res = new int[required];
            for (int i = 0; i < required; i++) {
                long r1 = Math.round(reRes[i]);
                long r2 = Math.round(imRes[i]);
                long r3 = Math.round(imRes[size - i]);
                res[i] = (int) ((r1 + ((r2 % mod) << 15) + ((r3 % mod) << 30)) % mod);
            }
            return res;
        }

        void transform(double[] re, double[] im, boolean inv) {
            int n = re.length;
            int shift = 32 - Integer.numberOfTrailingZeros(n);
            for (int i = 1; i < n; i++) {
                int j = Integer.reverse(i << shift) >>> shift;
                if (i < j) {
                    double tmp = re[i]; re[i] = re[j]; re[j] = tmp;
                    tmp = im[i]; im[i] = im[j]; im[j] = tmp;
                }
            }

            for (int len = 2; len <= n; len <<= 1) {
                int mid = len >> 1;
                int step = cosTable.length / len;

                for (int start = 0; start < n; start += len) {
                    for (int idx = 0, w = 0; idx < mid; idx++, w += step) {
                        double twRe = inv ? cosNegTable[mid + idx] : cosTable[mid + idx];
                        double twIm = inv ? sinNegTable[mid + idx] : sinTable[mid + idx];

                        int i1 = start + idx;
                        int i2 = start + idx + mid;

                        double uRe = re[i1];
                        double uIm = im[i1];
                        double vRe = re[i2] * twRe - im[i2] * twIm;
                        double vIm = re[i2] * twIm + im[i2] * twRe;

                        re[i1] = uRe + vRe;
                        im[i1] = uIm + vIm;
                        re[i2] = uRe - vRe;
                        im[i2] = uIm - vIm;
                    }
                }
            }

            if (inv) {
                double invN = 1.0 / n;
                for (int i = 0; i < n; i++) {
                    re[i] *= invN;
                    im[i] *= invN;
                }
            }
        }
    }

    static class Reader {
        final InputStream src;
        final byte[] chunk = new byte[1024];
        int ptr = 0;
        int count = 0;

        Reader(InputStream src) {
            this.src = src;
        }

        int nextInt() {
            int ch = read();
            while (isSpace(ch)) ch = read();
            int sgn = 1;
            if (ch == '-') {
                sgn = -1;
                ch = read();
            }
            int val = 0;
            do {
                if (ch < '0' || ch > '9') throw new InputMismatchException();
                val = val * 10 + ch - '0';
                ch = read();
            } while (!isSpace(ch));
            return val * sgn;
        }

        int read() {
            if (count == -1) throw new InputMismatchException();
            if (ptr >= count) {
                ptr = 0;
                try {
                    count = src.read(chunk);
                } catch (Exception ex) {
                    throw new InputMismatchException();
                }
                if (count <= 0) return -1;
            }
            return chunk[ptr++] & 0xFF;
        }

        boolean isSpace(int ch) {
            return ch == ' ' || ch == '\n' || ch == '\r' || ch == '\t' || ch == -1;
        }
    }
}
